{
     "title": "CSCI-140: Computer Science for AP Students - Lesson Blueprint",
     "learningObjectives": [
       "Define and distinguish between static and dynamic data types using language reference specifications.",
       "Explain how objects, classes, and inheritance form the foundation of object-oriented design.",
       "Apply cohesion and minimal coupling principles to evaluate software quality in object-oriented structures."
     ],
     "beats": [
       {
         "title": "Course Foundations & Scope",
         "claim": "CSCI-140 provides the foundation for all subsequent Computer Science courses by covering first-year sequence material and stressing problem solving.",
         "example": "Students will use this course to prepare for advanced topics like algorithms, data structures, and software engineering.",
         "visualDirection": "Display a course roadmap graphic showing CSCI-140 as the central hub connecting to advanced CS courses.",
         "sourceIds": ["rit-csci-140"]
       },
       {
         "title": "Static vs. Dynamic Data Types",
         "claim": "Static and dynamic data types are fundamental concepts in modern software development, determining when type checking occurs.",
         "example": "In statically typed languages, variable types are checked at compile time, whereas dynamically typed languages check types at runtime.",
         "visualDirection": "Show a side-by-side comparison table of static vs. dynamic typing with code snippets highlighting compile-time vs. runtime type resolution.",
         "sourceIds": ["rit-csci-140"]
       },
       {
         "title": "Object-Oriented Design Foundations",
         "claim": "Object-oriented design relies on objects, classes, inheritance, and interfaces to structure software effectively.",
         "example": "A parent class defines shared behavior, while child classes inherit and extend that behavior through polymorphism.",
         "visualDirection": "Render a class diagram illustrating inheritance relationships between a base class and derived classes.",
         "sourceIds": ["rit-csci-140"]
       },
       {
         "title": "Abstract Data Types & Collections",
         "claim": "Object-oriented collection class libraries provide abstract data types like stacks, queues, maps, and trees for efficient data management.",
         "example": "A stack implements last-in-first-out behavior, while a queue implements first-in-first-out behavior for ordered data processing.",
         "visualDirection": "Animate a stack and queue data structure showing push/pop and enqueue/dequeue operations with labeled elements.",
         "sourceIds": ["rit-csci-140"]
       },
       {
         "title": "Software Qualities: Cohesion & Minimal Coupling",
         "claim": "Software quality in object-oriented design is measured by cohesion and minimal coupling to ensure maintainable code.",
         "example": "High cohesion means a class performs a single, well-defined purpose, while minimal coupling reduces dependencies between classes.",
         "visualDirection": "Display a before-and-after class diagram showing how refactoring improves cohesion and reduces coupling.",
         "sourceIds": ["rit-csci-140"]
       },
       {
         "title": "Exception Handling & Control Flow",
         "claim": "Exception handling interrupts normal control flow until a matching handler processes the error or it propagates.",
         "example": "A try-catch block catches a runtime error, allowing the program to recover or exit gracefully without crashing.",
         "visualDirection": "Show a control flow diagram with a normal path and an exception path branching to a handler block.",
         "sourceIds": ["python-language-reference"]
       },
       {
         "title": "Compiler & IR Concepts",
         "claim": "Compiler work separates parsing and semantic analysis from lowering, verification, optimization, and target-specific code generation.",
         "example": "LLVM IR serves as a typed, SSA-based intermediate representation that enables cross-platform optimization and code generation.",
         "visualDirection": "Illustrate a compiler pipeline diagram with stages: parsing, semantic analysis, lowering, verification, optimization, code generation.",
         "sourceIds": ["llvm-language-reference"]
       },
       {
         "title": "Python Language Model & Execution",
         "claim": "Python objects have identity, a type, and a value, and programs should be reasoned about through explicit state, control flow, and contracts.",
         "example": "Debugging separates syntax, runtime, and logical failures, while decomposition and abstraction reduce interacting concerns in Python code.",
         "visualDirection": "Show a Python object model diagram with identity, type, and value attributes, alongside a debugging workflow flowchart.",
         "sourceIds": ["python-language-reference"]
       },
       {
         "title": "Object-Oriented Design Patterns",
         "claim": "Elementary object-oriented design patterns are introduced to improve software structure and reusability.",
         "example": "The singleton pattern ensures a class has only one instance, while the factory pattern creates objects without specifying exact classes.",
         "visualDirection": "Display a simple UML diagram of a factory pattern with creator, product, and concrete product classes.",
         "sourceIds": ["rit-csci-140"]
       },
       {
         "title": "Practical Analysis Checklist",
         "claim": "Students must verify that software designs meet cohesion, minimal coupling, modifiability, and extensibility standards.",
         "example": "A checklist evaluates whether each class has a single responsibility, limited dependencies, and clear extension points for future features.",
         "visualDirection": "Show a printable checklist template with checkboxes for cohesion, coupling, modifiability, and extensibility evaluation.",
         "sourceIds": ["rit-csci-140"]
       }
     ]
   }
